<script setup>
import {ref,onMounted,computed} from 'vue';import {watchApps} from '../services/data';import {httpsCallable} from 'firebase/functions';import {functions} from '../firebase';
const props=defineProps(['user','profile']);const apps=ref([]),q=ref(''),cat=ref('Tümü'),ratingBusy=ref({});onMounted(()=>watchApps(v=>apps.value=v));const filtered=computed(()=>apps.value.filter(a=>(cat.value==='Tümü'||a.category===cat.value)&&(`${a.name} ${a.description}`.toLowerCase().includes(q.value.toLowerCase()))));function rating(a){return a.ratingCount?((a.ratingTotal/a.ratingCount).toFixed(1)):'Yeni'}
async function download(a){try{await httpsCallable(functions,'recordDownload')({appId:a.id});}catch{}window.open(a.downloadUrl,'_blank','noopener')}
async function rate(a,n){if(ratingBusy.value[a.id])return;ratingBusy.value[a.id]=true;try{await httpsCallable(functions,'rateApp')({appId:a.id,rating:n});}catch(e){alert(e.message)}finally{ratingBusy.value[a.id]=false}}
</script><template><div class="space"><div><h1>Uygulamalar</h1><p class="muted">Güvenlik taramasından geçen topluluk uygulamaları.</p></div></div><div class="row"><input class="field" style="max-width:420px" v-model="q" placeholder="Uygulama ara..."><select class="field" style="width:auto" v-model="cat"><option>Tümü</option><option>Oyun</option><option>Üretkenlik</option><option>Eğitim</option><option>Araçlar</option><option>Diğer</option></select></div><br><div v-if="filtered.length" class="apps-grid"><article v-for="a in filtered" :key="a.id" class="card"><img v-if="a.banner" :src="a.banner" class="banner"><div class="space"><h2>{{a.name}}</h2><span class="safe">🛡 Safe</span></div><p class="muted">{{a.description}}</p><div class="tags"><span class="tag">{{a.category}}</span><span class="tag">⬇ {{a.downloads||0}}</span><span class="tag">⭐ {{rating(a)}}</span></div><div class="rating"><span>Değerlendir:</span><button v-for="n in 5" :key="n" class="star-btn" :disabled="ratingBusy[a.id]" @click="rate(a,n)">{{n}}★</button></div><button class="btn" @click="download(a)">⬇ İndir</button></article></div><div v-else class="card empty">Aramana uygun uygulama bulunamadı.</div></template>
